"""Stage 1 – Parse raw report strings into structured rows."""

import re
from dataclasses import dataclass, field
from typing import List, Union

VALID_CATEGORIES = frozenset({"REVENUE", "COST", "HEADCOUNT"})
_PERIOD_RE = re.compile(r'^\d{4}-Q[1-4]$')


@dataclass
class ParsedRow:
    row_id: int
    category: str
    value: float
    period: str


@dataclass
class ParseError:
    raw: str
    reason: str
    stage: str = field(default="parse", init=False)


def parse(raw_inputs: List[str]) -> Union[List[ParsedRow], ParseError]:
    """Parse a list of raw report strings.

    Each string must have the format ``ROW_ID:CATEGORY:VALUE:PERIOD``.

    Returns a list of :class:`ParsedRow` on success, or a
    :class:`ParseError` identifying the first failing string and why.
    """
    results: List[ParsedRow] = []
    seen_ids: set = set()

    for raw in raw_inputs:
        parts = raw.split(":")
        if len(parts) != 4:
            return ParseError(
                raw=raw,
                reason=f"Expected 4 colon-separated fields, got {len(parts)}",
            )

        row_id_str, category, value_str, period = parts

        # ── ROW_ID ────────────────────────────────────────────────────
        try:
            row_id = int(row_id_str)
        except ValueError:
            return ParseError(
                raw=raw,
                reason=f"ROW_ID must be a positive integer, got '{row_id_str}'",
            )
        if row_id <= 0:
            return ParseError(
                raw=raw,
                reason=f"ROW_ID must be a positive integer, got '{row_id_str}'",
            )
        if row_id in seen_ids:
            return ParseError(
                raw=raw,
                reason=f"Duplicate ROW_ID: {row_id}",
            )
        seen_ids.add(row_id)

        # ── CATEGORY ──────────────────────────────────────────────────
        if category not in VALID_CATEGORIES:
            return ParseError(
                raw=raw,
                reason=(
                    f"CATEGORY must be one of REVENUE, COST, HEADCOUNT, "
                    f"got '{category}'"
                ),
            )

        # ── VALUE ─────────────────────────────────────────────────────
        try:
            value = float(value_str)
        except ValueError:
            return ParseError(
                raw=raw,
                reason=f"VALUE must be a decimal number, got '{value_str}'",
            )
        if category in ("REVENUE", "HEADCOUNT") and value < 0:
            return ParseError(
                raw=raw,
                reason=(
                    f"Negative VALUE not allowed for {category}, got {value}"
                ),
            )

        # ── PERIOD ────────────────────────────────────────────────────
        if not _PERIOD_RE.match(period):
            return ParseError(
                raw=raw,
                reason=(
                    f"PERIOD must be in format YYYY-QN (N=1–4), got '{period}'"
                ),
            )

        results.append(
            ParsedRow(row_id=row_id, category=category, value=value, period=period)
        )

    return results

"""Stage 3 – Format aggregated data into a plain-text table."""

from typing import Dict, List, Tuple

from .aggregate import AggregatedData

_SEP = "  "  # two-space column separator


# ── Value formatters ──────────────────────────────────────────────────────────

def _fmt_monetary(value: float) -> str:
    """Format a monetary value, e.g. 1234.56 → '$1,234.56', -200 → '-$200.00'."""
    if value < 0:
        return f"-${abs(value):,.2f}"
    return f"${value:,.2f}"


def _fmt_headcount(value: float) -> str:
    """Format a headcount value as a plain integer string."""
    return str(int(round(value)))


def _fmt_value(category: str, value: float) -> str:
    """Dispatch to the correct formatter based on category."""
    if category == "HEADCOUNT":
        return _fmt_headcount(value)
    return _fmt_monetary(value)


# ── Layout helper (shared with validate) ─────────────────────────────────────

def compute_layout(aggregated: AggregatedData) -> Tuple[int, List[str], Dict[str, int]]:
    """Return ``(label_width, col_keys, col_widths)`` for the table.

    *label_width*  – width of the leftmost (row-label) column.
    *col_keys*     – ordered list of column identifiers (periods + "TOTAL").
    *col_widths*   – mapping from col_key → allocated column width.
    """
    periods = aggregated.periods
    categories = aggregated.categories
    col_keys: List[str] = periods + ["TOTAL"]

    # Build all cell values so we can measure them
    # cell_values[col_key][row_label] = formatted string
    cell_values: Dict[str, Dict[str, str]] = {col: {} for col in col_keys}

    for cat in categories:
        for period in periods:
            val = aggregated.period_category[period][cat]
            cell_values[period][cat] = _fmt_value(cat, val)
        cell_values["TOTAL"][cat] = _fmt_value(cat, aggregated.category_totals[cat])

    # TOTAL row uses monetary formatting
    for period in periods:
        cell_values[period]["TOTAL"] = _fmt_monetary(aggregated.period_subtotals[period])
    cell_values["TOTAL"]["TOTAL"] = _fmt_monetary(aggregated.grand_total)

    all_row_labels = list(categories) + ["TOTAL"]

    # Label column: widest label (header for label column is blank)
    label_width = max((len(lbl) for lbl in all_row_labels), default=0)

    # Data columns: max of header width and all cell widths
    col_widths: Dict[str, int] = {}
    for col in col_keys:
        max_w = len(col)  # header text
        for lbl in all_row_labels:
            max_w = max(max_w, len(cell_values[col].get(lbl, "")))
        col_widths[col] = max_w

    return label_width, col_keys, col_widths


# ── Public formatter ──────────────────────────────────────────────────────────

def format_table(aggregated: AggregatedData) -> str:
    """Format *aggregated* data into a plain-text report table.

    Returns the table as a multi-line string.  Each data cell is
    right-aligned within its column; the row-label column is
    left-aligned.  Columns are separated by at least two spaces.
    """
    periods = aggregated.periods
    categories = aggregated.categories

    label_width, col_keys, col_widths = compute_layout(aggregated)

    def render_row(label: str, get_val) -> str:
        parts = [label.ljust(label_width)]
        for col in col_keys:
            parts.append(get_val(col).rjust(col_widths[col]))
        return _SEP.join(parts)

    lines: List[str] = []

    # Header
    lines.append(render_row("", lambda col: col))

    # Category rows
    for cat in categories:
        def _cat_val(col, _cat=cat):
            if col == "TOTAL":
                return _fmt_value(_cat, aggregated.category_totals[_cat])
            return _fmt_value(_cat, aggregated.period_category[col][_cat])

        lines.append(render_row(cat, _cat_val))

    # TOTAL row
    def _total_val(col):
        if col == "TOTAL":
            return _fmt_monetary(aggregated.grand_total)
        return _fmt_monetary(aggregated.period_subtotals[col])

    lines.append(render_row("TOTAL", _total_val))

    return "\n".join(lines)

"""Stage 4 – Validate the formatted table before export."""

from dataclasses import dataclass, field
from typing import Union

from .aggregate import AggregatedData
from .format import compute_layout, _fmt_value, _fmt_monetary

_SEP_LEN = 2  # two-space column separator


@dataclass
class ValidationError:
    reason: str
    stage: str = field(default="validate", init=False)


def _parse_number(s: str) -> float:
    """Parse a formatted cell value back to a float.

    Handles plain integers (headcount), ``$1,234.56`` and ``-$200.00``.
    """
    s = s.strip()
    if not s:
        return 0.0
    negative = s.startswith("-")
    if negative:
        s = s[1:]
    if s.startswith("$"):
        s = s[1:]
    s = s.replace(",", "")
    try:
        val = float(s)
    except ValueError:
        raise ValueError(f"Cannot parse '{s}' as a number")
    return -val if negative else val


def _extract_cells(line: str, label_width: int, col_keys: list, col_widths: dict) -> dict:
    """Extract the text content of each column in *line*.

    Returns a mapping ``col_key → stripped cell text``.
    """
    pos = label_width  # skip the label column
    result = {}
    for col in col_keys:
        pos += _SEP_LEN
        w = col_widths[col]
        result[col] = line[pos : pos + w].strip()
        pos += w
    return result


def validate_output(
    table: str, aggregated: AggregatedData
) -> Union[str, "ValidationError"]:
    """Validate the plain-text *table* against *aggregated* data.

    Checks:

    1. Every period from the input appears as a table column.
    2. The TOTAL column value for each category row equals the sum of
       that row's period values (within a small floating-point tolerance).
    3. No column is narrower than its header.

    Returns *table* unchanged on success, or a :class:`ValidationError`
    on the first failing check.
    """
    # ── Derive the expected layout (same logic as format_table) ──────
    label_width, col_keys, col_widths = compute_layout(aggregated)

    # ── Check 1: every input period appears as a column ──────────────
    for period in aggregated.periods:
        if period not in col_keys:
            return ValidationError(
                reason=f"Period '{period}' missing from table columns"
            )
        # Also verify it appears in the actual table string
        if period not in table:
            return ValidationError(
                reason=f"Period '{period}' not found in formatted table"
            )

    # ── Check 3: no column narrower than its header ───────────────────
    for col in col_keys:
        if col_widths[col] < len(col):
            return ValidationError(
                reason=(
                    f"Column '{col}' width ({col_widths[col]}) is narrower "
                    f"than its header ({len(col)})"
                )
            )
    # Also check label column (header is blank, so always OK, but be explicit)
    if label_width < 0:
        return ValidationError(reason="Label column has negative width")

    # ── Check 2: TOTAL column = sum of period values per row ─────────
    lines = table.split("\n")
    # lines[0] = header; lines[1..n-1] = category rows; lines[-1] = TOTAL row
    category_lines = lines[1 : 1 + len(aggregated.categories)]

    for cat, line in zip(aggregated.categories, category_lines):
        try:
            cells = _extract_cells(line, label_width, col_keys, col_widths)
        except Exception as exc:
            return ValidationError(
                reason=f"Could not extract cells from row '{cat}': {exc}"
            )

        try:
            period_nums = [_parse_number(cells[p]) for p in aggregated.periods]
            total_num = _parse_number(cells["TOTAL"])
        except ValueError as exc:
            return ValidationError(
                reason=f"Could not parse values in row '{cat}': {exc}"
            )

        expected_total = sum(period_nums)
        if abs(expected_total - total_num) > 0.005:
            return ValidationError(
                reason=(
                    f"TOTAL mismatch in row '{cat}': "
                    f"sum of periods={expected_total:.4f}, "
                    f"TOTAL column={total_num:.4f}"
                )
            )

    return table

